package mtls

import (
	"encoding/base64"
	"fmt"
	"net"
	"strings"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	. "github.com/kumahq/kuma/v3/test/framework"
	"github.com/kumahq/kuma/v3/test/framework/client"
	"github.com/kumahq/kuma/v3/test/framework/envs/universal"
)

func Policy() {
	meshName := "mtls-test"
	identityName := "mtls-test-identity"

	trustDomain := func() string {
		return MeshIdentityTrustDomain(meshName, universal.Cluster)
	}

	// autogeneratedCAIdentity mints a self-signed CA in the control plane.
	autogeneratedCAIdentity := func() InstallFunc {
		return MeshIdentityBundled(meshName, identityName)
	}

	// providedCAIdentity hands the control plane a CA of our own. The fixtures
	// are base64-encoded PEM, and InsecureInline takes the PEM itself, so they
	// are decoded here and folded into a double-quoted YAML scalar.
	providedCAIdentity := func(certBase64, keyBase64 string) InstallFunc {
		return func(cluster Cluster) error {
			inline := func(encoded string) (string, error) {
				pem, err := base64.StdEncoding.DecodeString(encoded)
				if err != nil {
					return "", err
				}
				return strings.ReplaceAll(string(pem), "\n", `\n`), nil
			}
			cert, err := inline(certBase64)
			if err != nil {
				return err
			}
			key, err := inline(keyBase64)
			if err != nil {
				return err
			}
			return YamlUniversal(fmt.Sprintf(`
type: MeshIdentity
name: %s
mesh: %s
spec:
  selector:
    dataplane:
      matchLabels: {}
  spiffeID:
    trustDomain: "{{ .Mesh }}.{{ .Zone }}.mesh.local"
  provider:
    type: Bundled
    bundled:
      meshTrustCreation: Enabled
      insecureAllowSelfSigned: true
      certificateParameters:
        expiry: 24h
      ca:
        certificate:
          type: InsecureInline
          insecureInline:
            value: "%s"
        privateKey:
          type: InsecureInline
          insecureInline:
            value: "%s"
`, identityName, meshName, cert, key))(cluster)
		}
	}

	meshTLS := func(mode string) InstallFunc {
		return YamlUniversal(fmt.Sprintf(`
type: MeshTLS
name: mode
mesh: %s
spec:
  targetRef:
    kind: Mesh
  rules:
    - default:
        mode: %s
`, meshName, mode))
	}

	AfterEachFailure(func() {
		DebugUniversal(universal.Cluster, meshName)
	})

	E2EAfterEach(func() {
		Expect(universal.Cluster.DeleteMeshApps(meshName)).To(Succeed())
		Expect(universal.Cluster.DeleteMesh(meshName)).To(Succeed())
	})

	curlAddr := func(addr string, fn ...client.CollectResponsesOptsFn) (string, string, error) {
		fn = append(fn, client.WithVerbose())

		return client.CollectResponse(
			universal.Cluster, "demo-client", addr, fn...,
		)
	}
	trafficAllowed := func(addr string, fn ...client.CollectResponsesOptsFn) {
		GinkgoHelper()
		expectation := func(g Gomega) {
			_, stderr, err := curlAddr(addr, fn...)
			g.Expect(err).ToNot(HaveOccurred())
			g.Expect(stderr).To(ContainSubstring("HTTP/1.1 200 OK"))
		}
		Eventually(expectation, "30s", "250ms").MustPassRepeatedly(10).Should(Succeed())
	}
	trafficBlocked := func(addr string, fn ...client.CollectResponsesOptsFn) {
		GinkgoHelper()
		expectation := func(g Gomega) {
			_, _, err := curlAddr(addr, fn...)
			g.Expect(err).To(HaveOccurred())
		}
		Eventually(expectation, "30s", "250ms").MustPassRepeatedly(10).Should(Succeed())
	}

	Describe("should support mode", func() {
		publicAddress := func() string {
			return net.JoinHostPort(universal.Cluster.GetApp("test-server").GetIP(), "80")
		}
		setupTest := func(mode string) {
			err := NewClusterSetup().
				Install(MeshUniversal(meshName)).
				Install(meshTLS(mode)).
				Install(autogeneratedCAIdentity()).
				Install(TestServerUniversal("test-server", meshName, WithArgs([]string{"echo", "--instance", "echo-v1"}))).
				Install(DemoClientUniversal("demo-client", meshName, WithTransparentProxy(true))).
				Install(MeshTrafficPermissionAllowAllUniversalWorkloadIdentity(meshName, trustDomain())).
				Setup(universal.Cluster)
			Expect(err).ToNot(HaveOccurred())
		}
		It("Permissive server without TLS", func() {
			setupTest("Permissive")
			By("Check inside-mesh communication")
			trafficAllowed("test-server.svc.mesh.local")

			By("Check outside-mesh communication")
			trafficAllowed(publicAddress())
		})
		It("Strict server without TLS", func() {
			setupTest("Strict")
			By("Check inside-mesh communication")
			trafficAllowed("test-server.svc.mesh.local")

			By("Check outside-mesh communication")
			trafficBlocked(publicAddress())
		})
		It("Permissive server with TLS", func() {
			setupTest("Permissive")
			By("Check inside-mesh communication")
			trafficAllowed("test-server.svc.mesh.local", client.WithCACert("/kuma/server.crt"))

			By("Check outside-mesh communication")
			// we're using curl with '--resolve' flag to verify certificate Common Name 'test-server.mesh'
			host := universal.Cluster.GetApp("test-server").GetIP()
			trafficAllowed(publicAddress(),
				client.WithCACert("/kuma/server.crt"),
				client.Resolve("test-server.mesh:80", fmt.Sprintf("[%s]", host)))
		})
		It("Strict server with TLS", func() {
			setupTest("Strict")
			By("Check inside-mesh communication")
			trafficAllowed("test-server.svc.mesh.local", client.WithCACert("/kuma/server.crt"))

			By("Check outside-mesh communication")
			// we're using curl with '--resolve' flag to verify certificate Common Name 'test-server.mesh'
			host := universal.Cluster.GetApp("test-server").GetIP()
			trafficBlocked(publicAddress(),
				client.WithCACert("/kuma/server.crt"),
				client.Resolve("test-server.mesh:80", fmt.Sprintf("[%s]", host)))
		})
	})

	It("enabling Permissive with no failed requests", func() {
		Expect(universal.Cluster.Install(MeshUniversal(meshName))).To(Succeed())

		// Disable retries so that we see every failed request
		kumactl := universal.Cluster.GetKumactlOptions()
		Expect(kumactl.KumactlDelete("meshretry", fmt.Sprintf("mesh-retry-all-%s", meshName), meshName)).To(Succeed())

		// We must start client before server to test this properly. The client
		// should get XDS refreshes first to trigger the race condition fixed by
		// kumahq/kuma#3019
		Expect(universal.Cluster.Install(DemoClientUniversal("demo-client", meshName, WithTransparentProxy(true)))).To(Succeed())

		Expect(universal.Cluster.Install(TestServerUniversal("test-server", meshName, WithArgs([]string{"echo", "--instance", "echo-v1"})))).To(Succeed())

		By("Check inside-mesh communication")
		trafficAllowed("test-server.svc.mesh.local")

		By("Enable permissive mTLS")
		Expect(universal.Cluster.Install(MeshTrafficPermissionAllowAllUniversalWorkloadIdentity(meshName, trustDomain()))).To(Succeed())
		// MeshTLS goes in before the identity: it is a no-op while the proxies
		// have no certificate, so the inbounds never spend a moment in strict
		// mode.
		Expect(universal.Cluster.Install(meshTLS("Permissive"))).To(Succeed())
		Expect(universal.Cluster.Install(autogeneratedCAIdentity())).To(Succeed())

		By("inside-mesh communication never fails")
		Consistently(func(g Gomega) {
			_, stderr, err := curlAddr("test-server.svc.mesh.local")
			g.Expect(err).ToNot(HaveOccurred())
			g.Expect(stderr).To(ContainSubstring("HTTP/1.1 200 OK"))
		}).Should(Succeed())
	})

	DescribeTable("should enforce traffic permissions",
		func(identity func() InstallFunc) {
			err := NewClusterSetup().
				Install(MeshUniversal(meshName)).
				Install(TestServerUniversal("test-server", meshName, WithArgs([]string{"echo", "--instance", "echo-v1"}), WithLabels(map[string]string{"kuma.io/service": "test-server"}))).
				Install(DemoClientUniversal("demo-client", meshName, WithTransparentProxy(true))).
				Setup(universal.Cluster)
			Expect(err).ToNot(HaveOccurred())

			By("Can access test-server")
			trafficAllowed("test-server.svc.mesh.local")

			By("When the workloads get an identity")
			Expect(universal.Cluster.Install(identity())).To(Succeed())

			By("Can't access test-server")
			trafficBlocked("test-server.svc.mesh.local")

			By("When adding traffic-permission")
			perm := fmt.Sprintf(`
type: MeshTrafficPermission
name: example
mesh: "%s"
spec:
  targetRef:
    kind: Dataplane
    labels:
      kuma.io/service: test-server
  rules:
    - default:
        allow:
          - spiffeID:
              type: Prefix
              value: spiffe://%s/workload/demo-client
`, meshName, trustDomain())
			Expect(universal.Cluster.Install(YamlUniversal(perm))).To(Succeed())

			By("Can access test-server again")
			trafficAllowed("test-server.svc.mesh.local")
		},
		Entry("autogenerated CA", func() InstallFunc { return autogeneratedCAIdentity() }),
		Entry("provided Root CA", func() InstallFunc { return providedCAIdentity(rootCACert, rootCAKey) }),
		Entry("provided Intermediate CA", func() InstallFunc {
			return providedCAIdentity(intermediateCACert, intermediateCAKey)
		}),
	)
}
